Use of Buttons from within a workflow.

                private void Screen_LoadEvent(object sender, ScreenEventArgs e)
                {
                    //Override this screens keys
                    ScreenHandler.ButtonOverride.Disable(ActionKey.Enter);
                    ScreenHandler.ButtonOverride.Add(ActionKey.F10);

                }

Use of ScreenMap from workflow.

              private void Screen_EnterEvent(object sender, ScreenEventArgs e)
              {
                 string SomeData = "1234";
                 //Any screen after this one can now be mapped with
                 //ScreenMap.SomeKey to get the data to display.
                 ScreenMap.Add("SomeKey", SomeData);
              }

Use of Clear from event.

            private void Screen_LoadEvent(object sender, ScreenEventArgs e)
            {
               ScreenMap.Clear("SomeKey");
            }

Use of LaunchWorkflow from within a Workflow event.

               private void Screen_EnterEvent(object sender, ScreenEventArgs e)
               {
                   RFS_WorkflowAssembly WorkflowAssembly =
                                    new RFS_WorkflowAssembly(DataAccess, "WFA");

                   //Fetch assembly name either off of AssociatedWorkflow column or FormType
                  WorkflowAssembly.FormType = "ICS.Workflow.Base.ERP.Inventory.SomeWorkflowClass";
                  if (WorkflowAssembly.Fetch())
                  {
                     UserSession.LaunchWorkflow(WorkflowAssembly.AssociatedWorkflow,
                                                "SomeVersion",
                                                WorkflowAssembly.FormType);
                  }
               }
